insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 1, 'O tempo trabalha para quem começa cedo', 'entender que o tempo pesa mais do que o valor do primeiro aporte.', '["Quem guarda R$ 500 por mês durante 30 anos, com retorno real de 4% ao ano, chega a cerca de R$ 343 mil em valores de hoje, tendo aportado R$ 180 mil.", "Em 20 anos, com o mesmo aporte, chega a cerca de R$ 182 mil (aportou R$ 120 mil). Dez anos a menos quase cortam o resultado pela metade.", "O app mostra tudo em \"reais de hoje\": já descontada a inflação.", "São simulações com premissas, não promessas de retorno."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'O que mais pesa no resultado de longo prazo?', '[{"id": "a", "text": "O valor do primeiro aporte"}, {"id": "b", "text": "O tempo que o dinheiro fica aplicado"}, {"id": "c", "text": "O dia do mês em que você aporta"}]'::jsonb, 'b', 'Com juros compostos, cada ano a mais rende sobre tudo o que já foi acumulado.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=1;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'No exemplo de 30 anos, quanto dos R$ 343 mil veio dos seus aportes?', '[{"id": "a", "text": "Tudo"}, {"id": "b", "text": "R$ 180 mil"}, {"id": "c", "text": "Nada"}]'::jsonb, 'b', 'O restante, cerca de R$ 163 mil, veio dos rendimentos.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=1;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Os números do exemplo são:', '[{"id": "a", "text": "Uma garantia de retorno"}, {"id": "b", "text": "Uma simulação com premissas"}, {"id": "c", "text": "A média oficial do mercado"}]'::jsonb, 'b', 'Toda projeção depende das premissas escolhidas e pode não se realizar.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=1;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 2, 'A inflação encolhe o dinheiro em silêncio', 'entender poder de compra e por que o app usa reais de hoje.', '["Com inflação de 4% ao ano, os preços dobram em cerca de 18 anos.", "R$ 1.000 guardados embaixo do colchão compram, em 18 anos, o que hoje custa cerca de R$ 494.", "Por isso o plano fala em \"reais de hoje\": R$ 8.000 no plano significam o poder de compra de R$ 8.000 agora.", "Retorno real é o que sobra acima da inflação."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Com inflação de 4% ao ano, em quanto tempo os preços dobram, aproximadamente?', '[{"id": "a", "text": "8 anos"}, {"id": "b", "text": "18 anos"}, {"id": "c", "text": "40 anos"}]'::jsonb, 'b', 'Pela regra dos 72: 72 ÷ 4 = 18.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=2;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, '"Reais de hoje" significa:', '[{"id": "a", "text": "Valores com o poder de compra atual"}, {"id": "b", "text": "Valores sem juros"}, {"id": "c", "text": "Valores em dólar"}]'::jsonb, 'a', 'É a forma de comparar o futuro com a sua realidade de agora.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=2;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Um investimento rendeu 4% num ano em que a inflação foi de 4%. O retorno real foi de:', '[{"id": "a", "text": "4%"}, {"id": "b", "text": "8%"}, {"id": "c", "text": "Cerca de 0%"}]'::jsonb, 'c', 'O dinheiro cresceu, mas comprou o mesmo que antes.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=2;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 3, 'Juros compostos, o motor do plano', 'entender juros sobre juros e a regra dos 72.', '["Juros compostos rendem sobre o valor inicial e sobre os rendimentos anteriores.", "Regra dos 72: divida 72 pela taxa anual para saber em quantos anos o dinheiro dobra, aproximadamente.", "A 4% reais ao ano, o dinheiro dobra em cerca de 18 anos; a 6%, em cerca de 12.", "O que acelera o efeito: tempo e constância. O que atrapalha: resgates e trocas frequentes."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Juros compostos são:', '[{"id": "a", "text": "Juros calculados só sobre o valor inicial"}, {"id": "b", "text": "Juros que também rendem sobre os juros anteriores"}, {"id": "c", "text": "Juros cobrados por bancos"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=3;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'A 6% ao ano, o dinheiro dobra em cerca de:', '[{"id": "a", "text": "6 anos"}, {"id": "b", "text": "12 anos"}, {"id": "c", "text": "72 anos"}]'::jsonb, 'b', '72 ÷ 6 = 12.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=3;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'O que mais ajuda os juros compostos?', '[{"id": "a", "text": "Tempo e constância"}, {"id": "b", "text": "Mudar de aplicação todo mês"}, {"id": "c", "text": "Resgatar os rendimentos"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=3;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 4, 'Quanto custa a vida que você quer', 'chegar a uma renda mensal desejada realista.', '["Pense em reais de hoje: quanto você precisaria por mês para viver como gostaria.", "Comece pelas despesas atuais. Algumas tendem a subir (saúde), outras a cair (deslocamento para o trabalho).", "Um ponto de partida comum é a sua renda atual. Dá para ajustar depois.", "Um número aproximado agora vale mais que um número perfeito nunca."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Em que valor você deve pensar a renda desejada?', '[{"id": "a", "text": "Em reais de hoje"}, {"id": "b", "text": "Em reais do ano em que vai se aposentar"}, {"id": "c", "text": "Em dólares"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=4;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Qual despesa costuma subir na aposentadoria?', '[{"id": "a", "text": "Saúde"}, {"id": "b", "text": "Transporte para o trabalho"}, {"id": "c", "text": "Material escolar"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=4;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'A renda desejada pode mudar depois?', '[{"id": "a", "text": "Não, é definitiva"}, {"id": "b", "text": "Sim, o plano é revisado"}, {"id": "c", "text": "Só a cada dez anos"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=4;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 5, 'O que o INSS cobre e por que planejamos sem ele', 'entender os limites do INSS e a escolha de planejar sem depender dele.', '["Em 2026, o maior benefício pago pelo INSS é R$ 8.475,55 e o menor é um salário mínimo, R$ 1.621,00.", "O valor que você recebe depende de quanto e por quanto tempo contribuiu. Quem contribui pouco tende a receber perto do mínimo.", "O MEI contribui com 5% do salário mínimo e, em regra, tem direito à aposentadoria por idade no valor de um salário mínimo. O contribuinte individual pode pagar 20% sobre o que declara (entre o mínimo e o teto) ou 11% sobre o mínimo, no plano simplificado.", "Este app planeja sem o INSS por padrão. Se você tiver uma estimativa do Meu INSS, pode informá-la e ver os dois cenários."]'::jsonb, null, '[{"label": "Teto do INSS 2026 (meutudo)", "url": "https://meutudo.com.br/blog/noticias/2026/01/12/teto-do-inss-em-2026-e-de-r-8-47555-confira-faixas-e-aliquotas/"}, {"label": "Alíquotas por categoria (Barbieri Advogados)", "url": "https://www.barbieriadvogados.com/teto-do-inss-2026-valor-tabela-historica/"}]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Qual é o maior benefício pago pelo INSS em 2026?', '[{"id": "a", "text": "R$ 1.621,00"}, {"id": "b", "text": "R$ 8.475,55"}, {"id": "c", "text": "Não existe limite"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=5;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Por que o app planeja sem o INSS por padrão?', '[{"id": "a", "text": "Porque o INSS não paga nada"}, {"id": "b", "text": "Para o plano funcionar mesmo que o benefício seja menor do que você espera"}, {"id": "c", "text": "Porque é proibido considerar o INSS"}]'::jsonb, 'b', 'O INSS entra como cenário extra, nunca como base.' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=5;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Onde consultar sua estimativa oficial?', '[{"id": "a", "text": "No Meu INSS"}, {"id": "b", "text": "Em redes sociais"}, {"id": "c", "text": "No app do seu banco"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=5;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 6, 'Quanto tempo dura uma aposentadoria', 'entender o horizonte do plano.', '["O risco de viver mais que o dinheiro é real. Por isso o plano usa, por padrão, um horizonte até os 95 anos.", "Quanto mais longo o horizonte, maior o patrimônio necessário.", "Você pode mudar o horizonte nas premissas a qualquer momento."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Por que o horizonte padrão vai até os 95 anos?', '[{"id": "a", "text": "Para não ficar sem dinheiro se você viver mais"}, {"id": "b", "text": "Porque é a expectativa média de vida"}, {"id": "c", "text": "Por exigência legal"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=6;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Aumentar o horizonte de 85 para 95 anos faz o patrimônio necessário:', '[{"id": "a", "text": "Cair"}, {"id": "b", "text": "Subir"}, {"id": "c", "text": "Ficar igual"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=6;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'O horizonte pode ser alterado?', '[{"id": "a", "text": "Sim, nas premissas"}, {"id": "b", "text": "Não"}, {"id": "c", "text": "Só pagando"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=6;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 7, 'Defina seu objetivo', 'escolher idade e renda desejadas.', '["Aposentar mais cedo significa menos anos acumulando e mais anos consumindo.", "Aposentadoria não precisa ser tudo ou nada: muita gente reduz o trabalho aos poucos.", "O objetivo orienta decisões; não é uma promessa nem uma regra fixa."]'::jsonb, 'set_goal', '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Antecipar a aposentadoria em 5 anos geralmente:', '[{"id": "a", "text": "Reduz o aporte necessário"}, {"id": "b", "text": "Aumenta o aporte necessário"}, {"id": "c", "text": "Não muda nada"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=7;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Por quê?', '[{"id": "a", "text": "Menos anos para acumular e mais anos para consumir"}, {"id": "b", "text": "Os juros mudam"}, {"id": "c", "text": "A inflação deixa de existir"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=7;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Seu objetivo é:', '[{"id": "a", "text": "Uma meta para orientar decisões"}, {"id": "b", "text": "Uma promessa de resultado"}, {"id": "c", "text": "Uma regra que não pode mudar"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=7;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 8, 'A reserva de emergência vem antes', 'entender por que a reserva protege o plano de aposentadoria.', '["Sem reserva, um imprevisto vira dívida ou resgate antecipado do dinheiro da aposentadoria.", "Para quem tem renda variável, muitos educadores financeiros sugerem de 6 a 12 meses de despesas.", "A reserva pede aplicação com resgate rápido e baixo risco.", "Dá para construir a reserva e começar a aposentadoria em paralelo, com valores menores."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Por que a reserva vem antes?', '[{"id": "a", "text": "Evita resgatar a aposentadoria ou se endividar num imprevisto"}, {"id": "b", "text": "Rende mais"}, {"id": "c", "text": "É obrigatória por lei"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=8;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Para renda variável, uma referência comum é:', '[{"id": "a", "text": "1 mês de despesas"}, {"id": "b", "text": "6 a 12 meses de despesas"}, {"id": "c", "text": "5 anos de despesas"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=8;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'A característica mais importante da reserva é:', '[{"id": "a", "text": "Poder sacar rápido, com baixo risco"}, {"id": "b", "text": "Ter o maior retorno possível"}, {"id": "c", "text": "Ter prazo longo de carência"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=8;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 9, 'Do objetivo ao patrimônio-alvo', 'entender como a renda desejada vira um valor a acumular.', '["Patrimônio-alvo é quanto você precisa ter na aposentadoria para pagar a renda desejada até o fim do horizonte.", "Exemplo: R$ 8.000 por mês dos 60 aos 95 anos, com retorno real de 4%, pedem cerca de R$ 1,82 milhão em valores de hoje.", "Se você contar com um INSS estimado de R$ 4.500, o valor necessário cai para cerca de R$ 798 mil.", "O app faz essa conta por você e mostra as premissas."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'O patrimônio-alvo depende de:', '[{"id": "a", "text": "Renda desejada, horizonte e retorno"}, {"id": "b", "text": "Só da sua idade"}, {"id": "c", "text": "Do seu banco"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=9;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'No exemplo, considerar um INSS de R$ 4.500 reduz o alvo para cerca de:', '[{"id": "a", "text": "R$ 1,82 milhão"}, {"id": "b", "text": "R$ 798 mil"}, {"id": "c", "text": "Zero"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=9;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'O patrimônio-alvo é calculado em:', '[{"id": "a", "text": "Reais de hoje"}, {"id": "b", "text": "Reais do futuro"}, {"id": "c", "text": "Dólares"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=9;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 10, 'Retorno real e premissas honestas', 'escolher premissas de retorno com prudência.', '["O plano usa retorno real, acima da inflação. Os pontos de partida são 2% (conservador), 4% (central) e 6% (otimista) ao ano, e você pode mudar.", "Premissas otimistas demais fazem o plano parecer fácil e escondem o esforço necessário.", "Rentabilidade passada não garante rentabilidade futura."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Retorno real é:', '[{"id": "a", "text": "O retorno acima da inflação"}, {"id": "b", "text": "O retorno sem impostos"}, {"id": "c", "text": "O retorno garantido"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=10;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Usar uma premissa de retorno alta demais tende a:', '[{"id": "a", "text": "Subestimar o aporte necessário"}, {"id": "b", "text": "Superestimar o aporte necessário"}, {"id": "c", "text": "Não mudar nada"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=10;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Rentabilidade passada:', '[{"id": "a", "text": "Garante a futura"}, {"id": "b", "text": "Não garante a futura"}, {"id": "c", "text": "É sempre igual à futura"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=10;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 11, 'Três cenários em vez de um número', 'usar cenários para decidir com incerteza.', '["O futuro é incerto; três cenários mostram uma faixa de resultados possíveis.", "Uma prática prudente: escolher o aporte olhando o cenário central e conferir se o conservador não fica longe demais.", "Os cenários mudam quando você muda as premissas, e o plano é revisado todo ano."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Por que olhar três cenários?', '[{"id": "a", "text": "Porque o futuro é incerto"}, {"id": "b", "text": "Para escolher o mais bonito"}, {"id": "c", "text": "Por exigência legal"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=11;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Uma prática prudente é escolher o aporte com base:', '[{"id": "a", "text": "No cenário otimista"}, {"id": "b", "text": "No central, conferindo o conservador"}, {"id": "c", "text": "Em nenhum deles"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=11;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Os cenários mudam quando:', '[{"id": "a", "text": "Você muda as premissas"}, {"id": "b", "text": "Nunca"}, {"id": "c", "text": "Só no fim do ano"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=11;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 12, 'Custos que parecem pequenos', 'perceber o efeito dos custos no longo prazo.', '["R$ 500 por mês durante 30 anos a 4% reais chegam a cerca de R$ 343 mil. A 3%, cerca de R$ 289 mil: cerca de R$ 53 mil a menos, ou 16%.", "Um custo de 1% ao ano tem praticamente o mesmo efeito.", "Em planos de previdência, vale olhar a taxa de administração e a taxa de carregamento antes de contratar.", "No app, você pode informar um custo anual nas premissas."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'No exemplo, 1 ponto percentual a menos por ano, em 30 anos, reduziu o resultado em cerca de:', '[{"id": "a", "text": "1%"}, {"id": "b", "text": "16%"}, {"id": "c", "text": "50%"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=12;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Em planos de previdência, um custo a verificar é:', '[{"id": "a", "text": "A taxa de carregamento"}, {"id": "b", "text": "O IPVA"}, {"id": "c", "text": "A tarifa do Pix"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=12;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Quando comparar custos?', '[{"id": "a", "text": "Antes de contratar"}, {"id": "b", "text": "Nunca"}, {"id": "c", "text": "Só no resgate"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=12;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 13, 'Onde se guarda para o longo prazo (visão geral)', 'conhecer os tipos de aplicação de longo prazo, sem recomendação de produto.', '["Algumas opções comuns: títulos públicos atrelados à inflação, planos de previdência (PGBL e VGBL), fundos e ETFs.", "PGBL: permite deduzir as contribuições da base do imposto de renda, até 12% da renda bruta tributável, para quem faz a declaração completa (há outras condições). No resgate, o imposto incide sobre o valor total.", "VGBL: não tem dedução; no resgate, o imposto incide só sobre os rendimentos. Desde 2026, aportes em VGBL acima de R$ 600 mil por ano, somando todas as seguradoras, pagam IOF de 5% sobre o excedente.", "Desde 2024, quem tem previdência pode escolher o regime de tributação (progressivo ou regressivo) até o primeiro resgate ou o início do benefício.", "Este app não recomenda produtos. Para escolher, compare custos e regras e, se precisar, consulte um profissional habilitado."]'::jsonb, null, '[{"label": "Lei 14.803/2024 (KPMG)", "url": "https://midia.kpmg.com.br/site/2024/01/COM240118-EXTERNO-TAX-NEWS-Financial-Services-Novas-Normas.html"}, {"label": "IOF sobre VGBL em 2026 (Brasil 61)", "url": "https://brasil61.com/n/novas-regras-do-iof-sobre-vgbl-entram-em-vigor-em-2026-bras2515406"}]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'O PGBL tende a fazer mais sentido para quem:', '[{"id": "a", "text": "Faz a declaração completa do imposto de renda"}, {"id": "b", "text": "É isento de imposto"}, {"id": "c", "text": "Quer resgatar em seis meses"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=13;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'No VGBL, o imposto no resgate incide sobre:', '[{"id": "a", "text": "O valor total"}, {"id": "b", "text": "Apenas os rendimentos"}, {"id": "c", "text": "Nada"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=13;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Desde 2024, o regime de tributação da previdência pode ser escolhido:', '[{"id": "a", "text": "Até o primeiro resgate ou o início do benefício"}, {"id": "b", "text": "Só na contratação"}, {"id": "c", "text": "Depois do último resgate"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=13;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 14, 'Monte seu plano', 'criar o plano com um aporte possível hoje.', '["Escolha um aporte que caiba no seu orçamento hoje, mesmo que seja menor do que o necessário.", "O app mostra o aporte necessário e a distância até ele. Começar e revisar vale mais do que esperar o valor ideal.", "O aporte é uma decisão sua, não uma recomendação do app."]'::jsonb, 'create_plan', '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Se o aporte necessário não cabe hoje, o melhor é:', '[{"id": "a", "text": "Não começar"}, {"id": "b", "text": "Começar com o que cabe e revisar"}, {"id": "c", "text": "Apostar para acelerar"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=14;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'O plano deve ser revisado:', '[{"id": "a", "text": "Quando a vida muda e uma vez por ano"}, {"id": "b", "text": "Nunca"}, {"id": "c", "text": "Todos os dias"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=14;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'O valor do aporte é:', '[{"id": "a", "text": "Uma decisão sua"}, {"id": "b", "text": "Uma recomendação do app"}, {"id": "c", "text": "Uma obrigação legal"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=14;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 15, 'Pague-se primeiro', 'automatizar o aporte.', '["\"Pagar-se primeiro\" é separar o aporte assim que o dinheiro entra, e não guardar o que sobra no fim do mês.", "Programe uma transferência automática no seu banco para o dia em que você recebe.", "O app não movimenta dinheiro: quem programa é você."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, '"Pagar-se primeiro" significa:', '[{"id": "a", "text": "Separar o aporte assim que o dinheiro entra"}, {"id": "b", "text": "Guardar o que sobrar no fim do mês"}, {"id": "c", "text": "Gastar primeiro com você mesmo"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=15;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'O melhor dia para a transferência é:', '[{"id": "a", "text": "Logo depois de receber"}, {"id": "b", "text": "O último dia do mês"}, {"id": "c", "text": "Qualquer dia aleatório"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=15;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Quem programa a transferência?', '[{"id": "a", "text": "Você, no seu banco"}, {"id": "b", "text": "O app"}, {"id": "c", "text": "O INSS"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=15;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 16, 'Renda variável sem drama', 'ter uma regra de aporte que funcione com renda irregular.', '["Uma regra simples: um aporte mínimo fixo todo mês e um percentual extra nos meses bons.", "Para PJ, definir um \"salário\" fixo para si ajuda a separar as finanças pessoais das da empresa.", "Nos meses bons, o extra pode ir primeiro para completar a reserva de emergência."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Uma estratégia para renda variável é:', '[{"id": "a", "text": "Aporte mínimo fixo e extra nos meses bons"}, {"id": "b", "text": "Só aportar quando sobrar"}, {"id": "c", "text": "Aportar tudo de uma vez num mês"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=16;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Para PJ, definir um salário fixo para si ajuda a:', '[{"id": "a", "text": "Separar finanças pessoais e da empresa"}, {"id": "b", "text": "Pagar sempre menos imposto"}, {"id": "c", "text": "Nada"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=16;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Nos meses bons, o extra pode ir primeiro para:', '[{"id": "a", "text": "Completar a reserva de emergência"}, {"id": "b", "text": "Apostas"}, {"id": "c", "text": "Compras por impulso"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=16;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 17, 'O mês difícil', 'saber o que fazer quando não dá para aportar.', '["Reduzir ou pausar não é desistir. O importante é retomar.", "Pegar empréstimo para manter o aporte quase nunca faz sentido: os juros do crédito costumam ser maiores que o retorno.", "No app, um mês sem aporte fica registrado e o plano segue."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Num mês apertado, o mais saudável é:', '[{"id": "a", "text": "Desistir do plano"}, {"id": "b", "text": "Reduzir ou pausar e retomar depois"}, {"id": "c", "text": "Usar o cartão de crédito para aportar"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=17;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Pegar empréstimo para manter o aporte:', '[{"id": "a", "text": "Geralmente não faz sentido"}, {"id": "b", "text": "É o recomendado"}, {"id": "c", "text": "É obrigatório"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=17;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'No app, um mês sem aporte:', '[{"id": "a", "text": "Apaga seu progresso"}, {"id": "b", "text": "Fica registrado e você segue"}, {"id": "c", "text": "Bloqueia sua conta"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=17;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 18, 'Constância vale mais que valor', 'entender como o app mede progresso.', '["Registrar o aporte do mês dá o mesmo XP para qualquer valor. O que conta é a regularidade.", "Seu progresso é comparado com a sua própria trajetória, nunca com a de outras pessoas.", "O fio da constância mostra mês a mês o hábito que você está construindo."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'No app, quem ganha mais XP ao registrar um aporte?', '[{"id": "a", "text": "Quem aporta mais"}, {"id": "b", "text": "Todos ganham o mesmo"}, {"id": "c", "text": "Quem tem mais patrimônio"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=18;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'O que mais influencia o resultado no longo prazo?', '[{"id": "a", "text": "Regularidade e tempo"}, {"id": "b", "text": "Acertar o melhor mês"}, {"id": "c", "text": "Sorte"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=18;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Com quem comparar seu progresso?', '[{"id": "a", "text": "Com a sua própria trajetória"}, {"id": "b", "text": "Com o patrimônio dos amigos"}, {"id": "c", "text": "Com influenciadores"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=18;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 19, 'Quando revisar o plano', 'criar o hábito de revisão.', '["Revisão rápida todo mês: menos de um minuto para confirmar as premissas.", "Ajuste quando a vida muda: renda, família, trabalho, cidade.", "Revisão completa uma vez por ano.", "Revisar para baixo faz parte do processo."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'Qual destes é um motivo para ajustar o plano?', '[{"id": "a", "text": "Mudança de renda"}, {"id": "b", "text": "Troca de celular"}, {"id": "c", "text": "Um app novo"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=19;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Com que frequência fazer a revisão completa?', '[{"id": "a", "text": "Uma vez por ano"}, {"id": "b", "text": "Todos os dias"}, {"id": "c", "text": "A cada dez anos"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=19;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Revisar o plano para baixo é:', '[{"id": "a", "text": "Um fracasso"}, {"id": "b", "text": "Parte normal do processo"}, {"id": "c", "text": "Proibido"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=19;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 20, 'Armadilhas no caminho', 'reconhecer promessas e práticas perigosas.', '["Retorno alto e \"garantido\" é sinal de alerta de golpe.", "Apostas são entretenimento com perda esperada, não investimento.", "Nunca compartilhe senhas nem códigos de acesso. Desconfie de urgência."]'::jsonb, null, '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, '"Retorno garantido de 5% ao mês" é:', '[{"id": "a", "text": "Uma oportunidade"}, {"id": "b", "text": "Um sinal de alerta"}, {"id": "c", "text": "Normal no mercado"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=20;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'Apostas esportivas são:', '[{"id": "a", "text": "Uma forma de investimento"}, {"id": "b", "text": "Entretenimento com perda esperada"}, {"id": "c", "text": "Previdência"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=20;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 3, 'Alguém pede sua senha para "investir por você". Você:', '[{"id": "a", "text": "Aceita"}, {"id": "b", "text": "Recusa"}, {"id": "c", "text": "Negocia"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=20;
insert into public.lessons (program_id, day, title, objective, key_points, action_key, sources, status) select id, 21, 'Seu primeiro aporte', 'registrar o primeiro aporte e entrar no ciclo mensal.', '["Registre o aporte que você fez (ou vai fazer) este mês. O valor é opcional e só você vê.", "Ative o lembrete mensal no dia em que seu dinheiro entra.", "A partir de agora: uma missão por semana, o registro mensal e a revisão anual."]'::jsonb, 'first_contribution', '[]'::jsonb, 'rascunho' from public.programs where slug='plano-sem-inss-21';
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 1, 'O que acontece depois do dia 21?', '[{"id": "a", "text": "O app acaba"}, {"id": "b", "text": "Começam as missões semanais e o registro mensal"}, {"id": "c", "text": "Você precisa recomeçar"}]'::jsonb, 'b', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=21;
insert into public.lesson_questions (lesson_id, position, prompt, options, correct_option, explanation) select l.id, 2, 'O lembrete mensal serve para:', '[{"id": "a", "text": "Registrar o aporte e revisar rápido o plano"}, {"id": "b", "text": "Vender produtos"}, {"id": "c", "text": "Cobrar uma taxa"}]'::jsonb, 'a', '' from public.lessons l join public.programs p on p.id=l.program_id where p.slug='plano-sem-inss-21' and l.day=21;
